// IEC 60063 preferred resistor values (E24 canonical list, E96 generated by
// the standard formula) + voltage-divider pair search. Pure TS, no DOM.

/** Canonical E24 base values (IEC 60063 — includes the historical deviations
 * from the pure geometric formula, e.g. 2.7, 3.0, 3.3). */
export const E24: number[] = [
  1.0, 1.1, 1.2, 1.3, 1.5, 1.6, 1.8, 2.0, 2.2, 2.4, 2.7, 3.0,
  3.3, 3.6, 3.9, 4.3, 4.7, 5.1, 5.6, 6.2, 6.8, 7.5, 8.2, 9.1,
];

/** E96 base values from the IEC formula: round(10^(i/96), 3 significant digits). */
export const E96: number[] = Array.from({ length: 96 }, (_, i) => {
  const v = Math.pow(10, i / 96);
  return Math.round(v * 100) / 100;
});

export type ESeriesName = "E24" | "E96";

export function seriesValues(name: ESeriesName): number[] {
  return name === "E24" ? E24 : E96;
}

/** Nearest standard value to `target` (any decade). */
export function nearestValue(target: number, series: ESeriesName): number {
  if (!(target > 0) || !Number.isFinite(target)) return NaN;
  const decade = Math.pow(10, Math.floor(Math.log10(target)));
  const base = seriesValues(series);
  let best = NaN;
  let bestErr = Infinity;
  for (const d of [decade / 10, decade, decade * 10]) {
    for (const v of base) {
      const r = v * d;
      const err = Math.abs(r - target);
      if (err < bestErr) {
        bestErr = err;
        best = r;
      }
    }
  }
  return best;
}

export interface DividerOption {
  r1: number;
  r2: number;
  vout: number;
  /** Relative error vs the requested Vout (signed). */
  error: number;
  totalR: number;
}

/**
 * Find standard-value pairs for Vout = Vin·R2/(R1+R2).
 * R2 candidates come from one decade around `r2Scale` (e.g. 10_000);
 * R1 is snapped to the nearest standard value. Sorted by |error|.
 */
export function dividerOptions(
  vin: number,
  vout: number,
  series: ESeriesName,
  r2Scale = 10_000,
  count = 5,
): DividerOption[] {
  if (!(vin > 0) || !(vout > 0) || vout >= vin) return [];
  const base = seriesValues(series);
  const seen = new Set<string>();
  const options: DividerOption[] = [];
  for (const mul of [r2Scale / 10, r2Scale]) {
    for (const b of base) {
      const r2 = b * mul;
      const r1Ideal = (r2 * (vin - vout)) / vout;
      const r1 = nearestValue(r1Ideal, series);
      if (!Number.isFinite(r1) || r1 <= 0) continue;
      const key = `${r1}/${r2}`;
      if (seen.has(key)) continue;
      seen.add(key);
      const actual = (vin * r2) / (r1 + r2);
      options.push({ r1, r2, vout: actual, error: (actual - vout) / vout, totalR: r1 + r2 });
    }
  }
  return options.sort((a, b) => Math.abs(a.error) - Math.abs(b.error)).slice(0, count);
}

/** Plain divider: Vout from Vin, R1 (top), R2 (bottom). */
export function dividerVout(vin: number, r1: number, r2: number): number {
  return (vin * r2) / (r1 + r2);
}
